def max_sum(arr):
    if not arr:
        return 0

    # Calculate the longest increasing subsequence (LIS) ending at each element
    lis = [0] * len(arr)
    for i in range(len(arr)):
        lis[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], arr[i] + lis[j])

    # Calculate the longest decreasing subsequence (LDS) starting at each element
    lds = [0] * len(arr)
    for i in range(len(arr) - 1, -1, -1):
        lds[i] = arr[i]
        for j in range(i + 1, len(arr)):
            if arr[i] > arr[j]:
                lds[i] = max(lds[i], arr[i] + lds[j])

    # Calculate the maximum sum of a bitonic subsequence
    max_sum = 0
    for i in range(len(arr)):
        max_sum = max(max_sum, lis[i] + lds[i] - arr[i])

    return max_sum

